/** 
 * Upon connection quitting, set exception and return result.
 */
@Override public void onUserQuit(QuitMessage msg){
  super.onUserQuit(msg);
  if (localUser(msg.getSource().getNick())) {
    try {
      synchronized (this.result) {
        this.result.setDone(new IllegalStateException("Local user quit."));
        this.result.notifyAll();
      }
    } catch (NullPointerException e) {
      // Handle NullPointerException gracefully, e.g., log or fallback initialization.
    }
  }
}
